def _segments(text, spans):
    out = []
    for s in spans:
        if isinstance(s, str):
            out.append(s)
        elif isinstance(s, dict):
            if "text" in s:
                out.append(str(s.get("text", "")))
            else:
                a = int(s.get("start", s.get("begin", 0)))
                b = int(s.get("end", s.get("stop", a)))
                out.append(text[a:b])
        elif isinstance(s, (list, tuple)) and len(s) >= 2:
            out.append(text[int(s[0]):int(s[1])])
        else:
            out.append("")
    return out

def _has(s, words):
    return any(w in s for w in words)

def _heading(s):
    t = s.strip().lower()
    if len(t) > 100:
        return False
    return _has(t, ("obligations", "non-disclosure", "nondisclosure", "permitted use", "restrictions on", "return of", "ownership", "remedies", "term and", "duration", "compelled disclosure", "required disclosure", "no solicitation", "non-solicitation", "miscellaneous", "general provisions"))

def _lead(out, xs, i):
    j = i - 1
    while j >= 0:
        t = xs[j].strip().lower()
        if len(t) <= 100 and (t.endswith(":") or t.endswith("following") or t.endswith("follows") or t in ("the recipient shall", "the receiving party shall", "recipient agrees", "the parties shall")):
            out.add(j)
            j -= 1
        else:
            break

def _definition_blocks(xs):
    blocks = []
    for i, s in enumerate(xs):
        t = s.lower()
        if "confidential information" in t and _has(t, (" means", " shall mean", " includes", " include all", "defined as")):
            e = i + 1
            while e < len(xs):
                q = xs[e].strip().lower()
                if _heading(q):
                    break
                if " means " in q and "confidential information" not in q and len(q) < 180:
                    break
                e += 1
            blocks.append((i, e))
    return blocks

def _intro(out, xs, i):
    j = i - 1
    while j >= 0 and not _heading(xs[j]):
        q = xs[j].lower()
        if _has(q, ("shall not include", "does not include", "shall not apply", "exceptions", "exclusions", "restrictions shall not apply")):
            out.add(j)
            return
        if len(q) > 250:
            return
        j -= 1

def propose_members(text, spans, public_hypothesis_key):
    xs = _segments(text, spans)
    low = [s.lower() for s in xs]
    out = set()
    k = public_hypothesis_key
    if k in ("nda-1", "nda-2", "nda-3"):
        for a, b in _definition_blocks(low):
            z = " ".join(low[a:b])
            take = k == "nda-1"
            if k == "nda-2":
                take = _has(z, ("technical", "business", "financial", "commercial", "marketing", "employee", "customer", "operational", "contractual", "personnel", "all information"))
            if k == "nda-3":
                take = _has(z, ("oral", "verbally", "spoken", "whether written", "regardless of form", "whatever form", "any form whatsoever"))
