        words = ("independently developed", "independent development", "developed independently", "independently derived", "independently create") if k == "nda-12" else ("from a third party", "from third parties", "third party having", "third party who", "another source", "source other than")
        for i, s in enumerate(low):
            if _has(s, words):
                out.add(i)
